// Decode into a caller-provided MW*MH byte map (0 walkable, 1 blocked).
inline void FwMapDecodeCollision(unsigned char* g) {
    int o = 0;
    for (int i = 0; i < (int)(sizeof(kFwMapRle)/sizeof(kFwMapRle[0])); i += 2) {
        const unsigned short v = kFwMapRle[i], run = kFwMapRle[i+1];
        for (int r = 0; r < run; ++r) g[o + r] = (unsigned char)(v ? 1 : 0);
        o += run;
    }
}

